      "豆芽，金针菇，莲藕，酸菜洗，煮熟备用，把鱼骨煎两边煎黄，倒入开水煮两分钟倒出备用，把蒜头，泡椒爆香",
      "把酸菜，姜片倒进去翻炒片刻，把煮好的鱼汤倒入煮五分钟，放入适量盐，蚝油，酱油，把酸菜，鱼骨捞起来，放入鱼片，轻轻搅拌一下，煮开即可捞起来，放上花椒，葱花，倒入热油即可",
      "开吃",
      "开吃"
