      "炒锅倒入四汤匙植物油（约30g），放入八角，开小火炸香。",
      "放入20g白糖翻炒。",
      "小火炒至糖融化，出小泡泡，成焦黄色（别炒过了，糖炒过了发苦）。",
      "倒入海虾，沿锅边淋入少许料酒，放入姜丝、蒜片、干辣椒段大火翻炒。",
