    "steps": [
      "新鲜虫草花择洗干净，黄瓜、小葱清洗干净；",
      "虫草花入开水中焯烫2分钟，捞出自然晾凉；",
      "黄瓜切细丝，小葱切末，大蒜剁碎；黄瓜的品种不一样，外皮的颜色和口感也不同，皮根据实际情况及个人喜好可去可不去；",
      "葱末、蒜末同入大碗，加适量生抽和醋混合均匀；料汁的量可多一些，以使主料能充分得到浸润；生抽的咸度和个人口味不同，所以盐酌情加入；",
      "黄瓜丝和料汁充分拌匀，腌2分钟，使黄瓜汁能被腌出来一些；",
      "加入虫草花、香油，充分拌匀即可食用；如果在热天，冷藏后食用口感更佳。",
      "凉拌黄瓜虫草花，清脆鲜美，酸辣爽口又开胃！"
    ],
    "note": ""
