      "搅拌均匀腌制15分钟。",
      "腌制后加入鸡蛋一个【里脊肉少可以选择小个鸡蛋】玉米淀粉【玉米淀粉可以把里脊肉裹一层，吃的时候外酥里嫩】",
      "搅拌上浆【淀粉的量可以拿一根肉丝看一下，肉丝挂上糊就正好】",
