      "等油温再次上升放里脊肉复炸再一次盛盘。",
      "锅里留一点底油，放入番茄酱开小火翻炒一下下。",
      "放入里脊肉反复颠几下，让每根里脊肉都裹上番茄酱。",
      "出锅撒点熟的白芝麻更香！"
