    "steps": [
      "西芹切小块，红萝卜去皮切小片。",
      "回锅肉平底锅中逼出油。",
      "回锅肉煎至金黄色下入红萝卜翻炒",
      "下入西芹翻炒至熟即可关火，下入适量盐，鸡精调味。",
      "咸香下饭。"
    ],
    "note": ""
