    "steps": [
      "五花肉先放到水里（冷水下锅）出血水，直到用筷子能比较轻松的戳进去，捞出，冲洗干净。",
      "晾凉后切片，尽量切的薄一些。",
      "姜、蒜切片，小葱切段，卷心菜洗净也切成小块。",
      "调味料全部准备好。",
      "锅里放油，先把五花肉片放进去煎，一片片的都把它扒拉开来。",
      "等肉片变得明显缩小，油有渗出来，就可以把肉片先盛出。",
      "锅里的油不要倒掉，把蒜片、姜片倒进去煸炒。",
      "花椒也在这个时候放进去。",
      "煸炒到有香味出来时，把豆瓣酱、甜面酱和老干妈放入一起煸炒。",
      "随后倒入肉片。"
    ],
