    "image": "cloud://cloud1-d4g2275j3b7f31ddd.636c-cloud1-d4g2275j3b7f31ddd-1467129221/dishes/seed-recipes/fcba9bd9.webp",
    "steps": [
      "鸡翅中加入两碗清水，几片姜片，一勺料酒，煮20分钟。煮过的汤汁需要留用。 牛肉丸和鱼豆腐也汆熟。",
      "我配菜也是随机，冰箱里有什么放什么。荤菜都要汆熟，蔬菜类全部都要汆烫半熟。",
      "我用海底捞的麻辣香锅调味料，这个超市都有卖。热锅倒油，放入葱姜蒜煸香。",
      "放入干辣椒煸香后再倒入麻辣香锅料包炒出香味。",
      "炒料包时火力不要过大。",
      "放入鸡翅中，翻炒几下后加入鱼豆腐，鹌鹑蛋，牛肉丸。加入一小碗之前煮鸡翅的汤汁。",
      "小煮一会后加入其他素菜，先加藕片和土豆片。",
      "翻炒几下加入菜花和木耳胡萝卜。",
      "最后加入虾和芹菜。翻炒片刻，可以用生抽和糖稍做调味。关火",
      "出锅撒上白芝麻和香菜，完美的颜值和味道。"
    ],
    "note": ""
