    "steps": [
      "鸡肉洗干净，冷水下锅放姜，葱，料酒，焯水。水开捞出鸡肉，洗干净，控干水分备用",
      "锅中倒油放几颗冰糖，炒至枣红色",
      "酱汁提前调好，生抽，蚝油，黄豆酱各一勺，多一点少一点差别也不大。",
      "土豆去皮切块再冲洗下土豆里面的淀粉 香菇提前泡发一下，切块",
      "炒至枣红色后，倒入鸡肉翻炒上色，上色后倒入我们调好的酱汁，再放姜和蒜，翻炒出酱香味",
      "最后加入热水末过鸡肉，大火烧开放香菇中火焖个10分钟，再加入土豆焖10分钟就可以了。",
      "最后加入青椒关火，有红椒的再放点红椒颜色更美丽。",
      "最后汤汁都不剩，被老公用来拌米饭吃了 所以： 你 准备好干饭了吗。",
      "最后汤汁都不剩，被老公用来拌米饭吃了 所以： 你 准备好干饭了吗。"
    ],
