    "image": "cloud://cloud1-d4g2275j3b7f31ddd.636c-cloud1-d4g2275j3b7f31ddd-1467129221/dishes/seed-recipes/d4d0fb62.webp",
    "steps": [
      "先准备制作蔬菜沙拉所用到的原料，甜玉米粒是即食的，一袋80g的量刚好。玉米粒不能算蔬菜，要算在主食里，所以吃了这一盘蔬菜沙拉后，就不要再吃主食了。",
      "小锅里烧开水，把秋葵洗净，整颗放进去煮2分钟；",
      "秋葵煮到时间后，再把切好的西兰花放进去焯1分钟，一起捞出沥水；",
      "把焯过的秋葵切成小段，和西兰花一起放到盘子里，再把小番茄切成小块，放到盘子里；",
      "制作沙拉的调味品——日式风味油醋汁；",
      "只需要挤在食材上面就可以了，用量不需要太多，根据自己的口味来安排即可；",
      "再来一包玉米粒，这个是即食甜玉米粒，配料很简单，吃起来也方便放心。",
      "把玉米粒倒在调过味的蔬菜上，再把蓝莓干也倒在上面，一盘好吃又好看的轻食沙拉就做好了。",
      "晚上给自己安排了这么一盘，没想到两个女儿还抢我的蓝莓干和玉米粒吃，无奈，又给她俩也做了一份，才能各自安好。"
    ],
