      "开始调制酱汁：东北大酱+甜面酱：耗油：番茄酱+豆瓣酱=2:2:1，搅拌均匀加入少许生抽，糖。如果酱汁比较稀，可以加点淀粉混合搅拌。",
      "用的是电磁炉，方便！锅里放入黄油或色拉油，加入葱姜蒜然后把青菜炒至3分熟。把鸡翅铺在上面，加点水小火焖10分钟。打开锅盖放入海虾，抹上调制好的酱汁，再盖上锅盖焖10分钟。",
