      "准备一个鸡蛋打散。",
      "准备适量的小虾米，洗净之后放旁边备用。",
      "锅内烧油，油热放入我们准备好的鸡蛋，炒成鸡蛋花。",
      "再放入适量的小虾米继续翻炒30秒左右。",
